import type { StemTerm } from '../types.js';

/**
 * The Ten Heavenly Stems (十天干).
 * Order matters: index is used for combination/clash arithmetic.
 */
export const STEMS: readonly StemTerm[] = [
  { key: 'jia', zh: '甲', en: 'Jia', pinyin: 'jiǎ', element: 'wood', polarity: 'yang', definition: 'Yang Wood — a towering tree; growth, initiative and uprightness.' },
  { key: 'yi', zh: '乙', en: 'Yi', pinyin: 'yǐ', element: 'wood', polarity: 'yin', definition: 'Yin Wood — flowering plants and vines; flexibility and adaptability.' },
  { key: 'bing', zh: '丙', en: 'Bing', pinyin: 'bǐng', element: 'fire', polarity: 'yang', definition: 'Yang Fire — the sun; brightness, generosity and visibility.' },
  { key: 'ding', zh: '丁', en: 'Ding', pinyin: 'dīng', element: 'fire', polarity: 'yin', definition: 'Yin Fire — a candle or lamp flame; focus, warmth and refinement.' },
  { key: 'wu', zh: '戊', en: 'Wu', pinyin: 'wù', element: 'earth', polarity: 'yang', definition: 'Yang Earth — a mountain or city wall; stability and reliability.' },
  { key: 'ji', zh: '己', en: 'Ji', pinyin: 'jǐ', element: 'earth', polarity: 'yin', definition: 'Yin Earth — garden soil; nourishment, patience and practicality.' },
  { key: 'geng', zh: '庚', en: 'Geng', pinyin: 'gēng', element: 'metal', polarity: 'yang', definition: 'Yang Metal — a sword or axe; decisiveness, justice and resolve.' },
  { key: 'xin', zh: '辛', en: 'Xin', pinyin: 'xīn', element: 'metal', polarity: 'yin', definition: 'Yin Metal — jewelry and fine ornaments; precision, elegance and sensitivity.' },
  { key: 'ren', zh: '壬', en: 'Ren', pinyin: 'rén', element: 'water', polarity: 'yang', definition: 'Yang Water — the ocean or a great river; movement, ambition and resourcefulness.' },
  { key: 'gui', zh: '癸', en: 'Gui', pinyin: 'guǐ', element: 'water', polarity: 'yin', definition: 'Yin Water — rain, dew and springs; intuition, gentleness and permeation.' },
] as const;

/** Lookup: Chinese character → stem term. */
export const STEM_BY_CHAR: Readonly<Record<string, StemTerm>> = Object.freeze(
  Object.fromEntries(STEMS.map((s) => [s.zh, s])),
);

/** Lookup: key → stem term. */
export const STEM_BY_KEY: Readonly<Record<string, StemTerm>> = Object.freeze(
  Object.fromEntries(STEMS.map((s) => [s.key, s])),
);

/**
 * Resolve a Heavenly Stem from a Chinese character.
 * Returns undefined for unknown characters instead of throwing,
 * so callers can render raw data defensively.
 */
export function stemByChar(char: string): StemTerm | undefined {
  return STEM_BY_CHAR[char];
}
