import type { GrowthStageKey, Term } from '../types.js';

export interface GrowthStageTerm extends Term {
  key: GrowthStageKey;
}

/**
 * The Twelve Growth Stages (十二长生) — the lifecycle of an element
 * across the twelve branches: birth → bathing → … → extinction → gestation → nurturing.
 */
export const GROWTH_STAGES: readonly GrowthStageTerm[] = [
  { key: 'birth', zh: '长生', en: 'Birth', pinyin: 'cháng shēng', definition: 'Newly born energy; the element enters its most promising phase.' },
  { key: 'bathing', zh: '沐浴', en: 'Bathing', pinyin: 'mù yù', definition: 'Infancy and washing; vulnerable, romantic and unstable energy.' },
  { key: 'crowning', zh: '冠带', en: 'Crowning', pinyin: 'guàn dài', definition: 'Coming of age; the element dresses up and starts to show capability.' },
  { key: 'officiating', zh: '临官', en: 'Officiating', pinyin: 'lín guān', definition: 'Taking office; mature, productive energy approaching its peak.' },
  { key: 'peak', zh: '帝旺', en: 'Peak', pinyin: 'dì wàng', definition: 'Imperial prosperity; the element at maximum strength.' },
  { key: 'decline', zh: '衰', en: 'Decline', pinyin: 'shuāi', definition: 'Energy past its prime, gradually weakening.' },
  { key: 'illness', zh: '病', en: 'Illness', pinyin: 'bìng', definition: 'Weakened energy, like sickness; low vitality.' },
  { key: 'death', zh: '死', en: 'Death', pinyin: 'sǐ', definition: 'Dormant energy; quiet, still and inactive.' },
  { key: 'tomb', zh: '墓', en: 'Tomb', pinyin: 'mù', definition: 'Stored energy locked in the tomb; latent, hoarded, awaiting a key.' },
  { key: 'extinction', zh: '绝', en: 'Extinction', pinyin: 'jué', definition: 'The lowest point; energy seemingly gone but about to turn.' },
  { key: 'gestation', zh: '胎', en: 'Gestation', pinyin: 'tāi', definition: 'Conception; a new cycle forming in secret.' },
  { key: 'nurturing', zh: '养', en: 'Nurturing', pinyin: 'yǎng', definition: 'Nourishment before birth; gentle preparation for the next cycle.' },
] as const;

/** Lookup: key → growth-stage term. */
export const GROWTH_STAGE_BY_KEY: Readonly<Record<string, GrowthStageTerm>> = Object.freeze(
  Object.fromEntries(GROWTH_STAGES.map((g) => [g.key, g])),
);

/** Lookup: Chinese label → growth-stage term. */
export const GROWTH_STAGE_BY_ZH: Readonly<Record<string, GrowthStageTerm>> = Object.freeze(
  Object.fromEntries(GROWTH_STAGES.map((g) => [g.zh, g])),
);

/** Resolve a growth stage from its Chinese label. */
export function growthStageByZh(zh: string): GrowthStageTerm | undefined {
  return GROWTH_STAGE_BY_ZH[zh];
}
