/** Lookup: key → general term. */
export const GENERAL_BY_KEY: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(GENERAL_TERMS.map((g) => [g.key, g])),
);

/** Lookup: Chinese label → general term. */
export const GENERAL_BY_ZH: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(GENERAL_TERMS.map((g) => [g.zh, g])),
);

/** Resolve a general term by key. */
export function generalBy(key: string): Term | undefined {
  return GENERAL_BY_KEY[key];
}

/** Resolve a general term by its Chinese label. */
export function generalByZh(zh: string): Term | undefined {
  return GENERAL_BY_ZH[zh];
}
