import type { BranchTerm } from '../types.js';

/**
 * The Twelve Earthly Branches (十二地支).
 * Order matters: index is used for clash/combination arithmetic.
 * Note: the key for 午 (Horse) is 'wuHorse' to avoid colliding with stem 戊 (wu).
 */
export const BRANCHES: readonly BranchTerm[] = [
  { key: 'zi', zh: '子', en: 'Zi', pinyin: 'zǐ', zodiacZh: '鼠', zodiacEn: 'Rat', element: 'water', hours: '23:00-01:00', definition: 'Rat branch — cardinal Water; midnight, winter solstice, hidden beginnings.' },
  { key: 'chou', zh: '丑', en: 'Chou', pinyin: 'chǒu', zodiacZh: '牛', zodiacEn: 'Ox', element: 'earth', hours: '01:00-03:00', definition: 'Ox branch — moist Earth; late winter, quiet accumulation.' },
  { key: 'yin', zh: '寅', en: 'Yin', pinyin: 'yín', zodiacZh: '虎', zodiacEn: 'Tiger', element: 'wood', hours: '03:00-05:00', definition: 'Tiger branch — Yang Wood; early spring, the start of the zodiac year.' },
  { key: 'mao', zh: '卯', en: 'Mao', pinyin: 'mǎo', zodiacZh: '兔', zodiacEn: 'Rabbit', element: 'wood', hours: '05:00-07:00', definition: 'Rabbit branch — Yin Wood; mid-spring, sunrise and expansion.' },
  { key: 'chen', zh: '辰', en: 'Chen', pinyin: 'chén', zodiacZh: '龙', zodiacEn: 'Dragon', element: 'earth', hours: '07:00-09:00', definition: 'Dragon branch — wet Earth; late spring, the water reservoir.' },
  { key: 'si', zh: '巳', en: 'Si', pinyin: 'sì', zodiacZh: '蛇', zodiacEn: 'Snake', element: 'fire', hours: '09:00-11:00', definition: 'Snake branch — Yin Fire; early summer, hidden heat.' },
  { key: 'wuHorse', zh: '午', en: 'Wu', pinyin: 'wǔ', zodiacZh: '马', zodiacEn: 'Horse', element: 'fire', hours: '11:00-13:00', definition: 'Horse branch — cardinal Fire; noon, summer solstice, peak Yang.' },
  { key: 'wei', zh: '未', en: 'Wei', pinyin: 'wèi', zodiacZh: '羊', zodiacEn: 'Goat', element: 'earth', hours: '13:00-15:00', definition: 'Goat branch — dry Earth; late summer, the wood reservoir.' },
  { key: 'shen', zh: '申', en: 'Shen', pinyin: 'shēn', zodiacZh: '猴', zodiacEn: 'Monkey', element: 'metal', hours: '15:00-17:00', definition: 'Monkey branch — Yang Metal; early autumn, the water birthplace.' },
  { key: 'you', zh: '酉', en: 'You', pinyin: 'yǒu', zodiacZh: '鸡', zodiacEn: 'Rooster', element: 'metal', hours: '17:00-19:00', definition: 'Rooster branch — cardinal Metal; mid-autumn, sunset and precision.' },
  { key: 'xu', zh: '戌', en: 'Xu', pinyin: 'xū', zodiacZh: '狗', zodiacEn: 'Dog', element: 'earth', hours: '19:00-21:00', definition: 'Dog branch — dry Earth; late autumn, the fire reservoir.' },
  { key: 'hai', zh: '亥', en: 'Hai', pinyin: 'hài', zodiacZh: '猪', zodiacEn: 'Pig', element: 'water', hours: '21:00-23:00', definition: 'Pig branch — Yang Water; early winter, the wood birthplace.' },
] as const;

/** Lookup: Chinese character → branch term. */
export const BRANCH_BY_CHAR: Readonly<Record<string, BranchTerm>> = Object.freeze(
  Object.fromEntries(BRANCHES.map((b) => [b.zh, b])),
);

/** Lookup: key → branch term. */
export const BRANCH_BY_KEY: Readonly<Record<string, BranchTerm>> = Object.freeze(
  Object.fromEntries(BRANCHES.map((b) => [b.key, b])),
);

/** Resolve an Earthly Branch from a Chinese character. */
export function branchByChar(char: string): BranchTerm | undefined {
  return BRANCH_BY_CHAR[char];
}
