/** Lookup: Chinese name → shen sha term. */
export const SHEN_SHA_BY_ZH: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(SHEN_SHA.map((s) => [s.zh, s])),
);

/** Lookup: key → shen sha term. */
export const SHEN_SHA_BY_KEY: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(SHEN_SHA.map((s) => [s.key, s])),
);

/**
 * Resolve a Shen Sha star from its Chinese name.
 * Unknown stars return undefined — render the raw name instead of dropping data.
 */
export function shenShaByZh(zh: string): Term | undefined {
  return SHEN_SHA_BY_ZH[zh];
}
