/** Lookup: key → interaction term. */
export const INTERACTION_BY_KEY: Readonly<Record<string, InteractionTerm>> = Object.freeze(
  Object.fromEntries(INTERACTION_TYPES.map((i) => [i.key, i])),
);

/** Lookup: English interaction enum (CLASH/TRINE/…) → interaction term. */
export const INTERACTION_BY_ENUM: Readonly<Record<string, InteractionTerm>> = Object.freeze(
  Object.fromEntries(
    INTERACTION_TYPES.filter((i) => i.enumCode).map((i) => [i.enumCode as string, i]),
  ),
);

/**
 * Ordered Chinese-verb → interaction-type map used to parse Chinese descriptions.
 * Longer / more specific verbs are matched first (三合 before 合, 会 before 合).
 */
const ZH_VERB_RULES: readonly [string, InteractionTypeKey][] = [
  ['三合', 'sanHe'],
  ['三会', 'sanHui'],
  ['会', 'sanHui'],
  ['相冲', 'liuChong'],
  ['冲', 'liuChong'],
  ['相刑', 'xiangXing'],
  ['刑', 'xiangXing'],
  ['相破', 'xiangPo'],
  ['破', 'xiangPo'],
  ['相害', 'xiangHai'],
  ['害', 'xiangHai'],
  ['六合', 'liuHe'],
  ['相合', 'liuHe'],
  ['合', 'liuHe'],
] as const;

/**
 * Resolve an interaction type from a Chinese description string
 * such as "午子相冲" or "卯子相刑". Returns undefined when no verb matches.
 */
export function interactionFromZh(desc: string): InteractionTerm | undefined {
  for (const [verb, key] of ZH_VERB_RULES) {
    if (desc.includes(verb)) return INTERACTION_BY_KEY[key];
  }
  return undefined;
}

/** Resolve an interaction type from an English enum value (CLASH, TRINE, …). */
export function interactionFromEnum(type: string): InteractionTerm | undefined {
  return INTERACTION_BY_ENUM[type];
}

