import type { TenGodKey, Term } from '../types.js';

export interface TenGodTerm extends Term {
  key: TenGodKey;
}

/**
 * The Ten Gods (十神) — relationship labels between each stem
 * and the Day Master, based on element and polarity.
 * Plus the Day Master itself, which engines emit as 日主 / 元男 / 元女.
 */
export const TEN_GODS: readonly TenGodTerm[] = [
  { key: 'biJian', zh: '比肩', en: 'Friend', pinyin: 'bǐ jiān', definition: 'Same element, same polarity as the Day Master: peers, siblings, competitors and self-reliance.' },
  { key: 'jieCai', zh: '劫财', en: 'Rob Wealth', pinyin: 'jié cái', definition: 'Same element, opposite polarity: rivals who share your resources; boldness and spending.' },
  { key: 'shiShen', zh: '食神', en: 'Eating God', pinyin: 'shí shén', definition: 'Element the Day Master generates, same polarity: creativity, enjoyment, expression and fertility.' },
  { key: 'shangGuan', zh: '伤官', en: 'Hurting Officer', pinyin: 'shāng guān', definition: 'Element the Day Master generates, opposite polarity: talent, rebellion and rule-breaking brilliance.' },
  { key: 'pianCai', zh: '偏财', en: 'Indirect Wealth', pinyin: 'piān cái', definition: 'Element the Day Master controls, same polarity: windfall money, business acumen and generosity.' },
  { key: 'zhengCai', zh: '正财', en: 'Direct Wealth', pinyin: 'zhèng cái', definition: 'Element the Day Master controls, opposite polarity: stable income, savings and (traditionally) the wife star.' },
  { key: 'qiSha', zh: '七杀', en: 'Seven Killings', pinyin: 'qī shā', definition: 'Element that controls the Day Master, same polarity: pressure, authority, courage and fierce ambition.' },
  { key: 'zhengGuan', zh: '正官', en: 'Direct Officer', pinyin: 'zhèng guān', definition: 'Element that controls the Day Master, opposite polarity: career, discipline, reputation and (traditionally) the husband star.' },
  { key: 'pianYin', zh: '偏印', en: 'Indirect Resource', pinyin: 'piān yìn', definition: 'Element that generates the Day Master, same polarity: unconventional learning, intuition and solitude.' },
  { key: 'zhengYin', zh: '正印', en: 'Direct Resource', pinyin: 'zhèng yìn', definition: 'Element that generates the Day Master, opposite polarity: education, protection, motherly support and credentials.' },
  { key: 'dayMaster', zh: '日主', en: 'Day Master', pinyin: 'rì zhǔ', definition: 'The Heavenly Stem of the Day Pillar — the reference point of the whole chart, representing the self.' },
] as const;

/** Lookup: key → ten-god term. */
export const TEN_GOD_BY_KEY: Readonly<Record<string, TenGodTerm>> = Object.freeze(
  Object.fromEntries(TEN_GODS.map((t) => [t.key, t])),
);

/**
 * Lookup: Chinese label → ten-god term.
 * Covers engine variants: 日主 / 元男 / 元女 all map to dayMaster;
 * 偏官 is a classic alias of 七杀.
 */
const TEN_GOD_ZH_ALIASES: Readonly<Record<string, TenGodKey>> = Object.freeze({
  比肩: 'biJian',
  劫财: 'jieCai',
  食神: 'shiShen',
  伤官: 'shangGuan',
  偏财: 'pianCai',
  正财: 'zhengCai',
  七杀: 'qiSha',
  偏官: 'qiSha',
  正官: 'zhengGuan',
  偏印: 'pianYin',
  枭神: 'pianYin',
  正印: 'zhengYin',
  日主: 'dayMaster',
  日元: 'dayMaster',
  元男: 'dayMaster',
  元女: 'dayMaster',
});

/** Resolve a Ten God from its Chinese label (aliases included). */
export function tenGodByZh(zh: string): TenGodTerm | undefined {
  const key = TEN_GOD_ZH_ALIASES[zh];
  return key ? TEN_GOD_BY_KEY[key] : undefined;
}
