/** Lookup: Na Yin Chinese name → term. */
export const NA_YIN_BY_ZH: Readonly<Record<string, NaYinTerm>> = Object.freeze(
  Object.fromEntries(NA_YIN.map((n) => [n.zh, n])),
);

/** Lookup: sexagenary pair (e.g. '甲子') → Na Yin term. */
export const NA_YIN_BY_GAN_ZHI: Readonly<Record<string, NaYinTerm>> = Object.freeze(
  Object.fromEntries(NA_YIN.flatMap((n) => n.pairs.map((p) => [p, n]))),
);

/** Resolve a Na Yin melody from its Chinese name or a sexagenary pair. */
export function naYinOf(input: string): NaYinTerm | undefined {
  return NA_YIN_BY_ZH[input] ?? NA_YIN_BY_GAN_ZHI[input];
}
