import type { ElementKey, Term } from '../types.js';

export interface ElementTerm extends Term {
  key: ElementKey;
}

/** The Five Elements (五行). */
export const ELEMENTS: readonly ElementTerm[] = [
  { key: 'wood', zh: '木', en: 'Wood', pinyin: 'mù', definition: 'Growth, expansion and benevolence; associated with spring and the east.' },
  { key: 'fire', zh: '火', en: 'Fire', pinyin: 'huǒ', definition: 'Heat, illumination and propriety; associated with summer and the south.' },
  { key: 'earth', zh: '土', en: 'Earth', pinyin: 'tǔ', definition: 'Stability, nourishment and trust; associated with the late-season transitions and the center.' },
  { key: 'metal', zh: '金', en: 'Metal', pinyin: 'jīn', definition: 'Structure, decisiveness and righteousness; associated with autumn and the west.' },
  { key: 'water', zh: '水', en: 'Water', pinyin: 'shuǐ', definition: 'Flow, wisdom and adaptability; associated with winter and the north.' },
] as const;

/** Lookup: Chinese character → element term. */
export const ELEMENT_BY_CHAR: Readonly<Record<string, ElementTerm>> = Object.freeze(
  Object.fromEntries(ELEMENTS.map((e) => [e.zh, e])),
);

/** Lookup: key → element term. */
export const ELEMENT_BY_KEY: Readonly<Record<string, ElementTerm>> = Object.freeze(
  Object.fromEntries(ELEMENTS.map((e) => [e.key, e])),
);

/** Resolve a Five Element from a Chinese character or an English key. */
export function elementOf(input: string): ElementTerm | undefined {
  return ELEMENT_BY_CHAR[input] ?? ELEMENT_BY_KEY[input];
}

/**
 * The generating (生) and controlling (克) cycles, as key pairs.
 * generating: Wood→Fire→Earth→Metal→Water→Wood
 * controlling: Wood→Earth→Water→Fire→Metal→Wood
 */
export const ELEMENT_CYCLES = {
  generating: [
    ['wood', 'fire'],
    ['fire', 'earth'],
    ['earth', 'metal'],
    ['metal', 'water'],
    ['water', 'wood'],
  ] as [ElementKey, ElementKey][],
  controlling: [
    ['wood', 'earth'],
    ['earth', 'water'],
    ['water', 'fire'],
    ['fire', 'metal'],
    ['metal', 'wood'],
  ] as [ElementKey, ElementKey][],
} as const;
