import type { Lang, Term } from './types.js';
import { STEMS } from './data/stems.js';
import { BRANCHES } from './data/branches.js';
import { ELEMENTS } from './data/elements.js';
import { TEN_GODS, tenGodByZh } from './data/tenGods.js';
import { GROWTH_STAGES } from './data/growthStages.js';
import { SHEN_SHA } from './data/shenSha.js';
import { NA_YIN, naYinOf } from './data/nayin.js';
import { INTERACTION_TYPES, interactionFromZh } from './data/interactions.js';
import { GENERAL_TERMS } from './data/general.js';

/* ------------------------------------------------------------------ *
 * Types
 * ------------------------------------------------------------------ */
export * from './types.js';

/* ------------------------------------------------------------------ *
 * Data modules (arrays, lookup maps and resolve functions)
 * ------------------------------------------------------------------ */
export * from './data/stems.js';
export * from './data/branches.js';
export * from './data/elements.js';
export * from './data/tenGods.js';
export * from './data/growthStages.js';
export * from './data/shenSha.js';
export * from './data/nayin.js';
export * from './data/interactions.js';
export * from './data/general.js';

/* ------------------------------------------------------------------ *
 * Unified registry
 * ------------------------------------------------------------------ */

/** Every term from every category, in a stable order. */
export const ALL_TERMS: readonly Term[] = Object.freeze([
  ...STEMS,
  ...BRANCHES,
  ...ELEMENTS,
  ...TEN_GODS,
  ...GROWTH_STAGES,
  ...SHEN_SHA,
  ...NA_YIN,
  ...INTERACTION_TYPES,
  ...GENERAL_TERMS,
]);

/** Lookup: unique term key → term. Keys are unique across all categories. */
export const TERM_BY_KEY: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(ALL_TERMS.map((term) => [term.key, term])),
);

/** Lookup: Chinese label → term (exact match). */
export const TERM_BY_ZH: Readonly<Record<string, Term>> = Object.freeze(
  Object.fromEntries(ALL_TERMS.map((term) => [term.zh, term])),
);

/**
 * Translate a term key into the requested language.
 * Returns the key itself when unknown, so rendering never breaks.
 *
 * @example t('dayMaster')        // 'Day Master'
 * @example t('dayMaster', 'zh')  // '日主'
 */
export function t(key: string, lang: Lang = 'en'): string {
  const term = TERM_BY_KEY[key];
  if (!term) return key;
  return lang === 'zh' ? term.zh : term.en;
}

/**
 * Best-effort translation of any raw engine value or term key.
 * Resolution order (exact → fuzzy):
 *   1. term key            (e.g. 'qiSha')
 *   2. exact Chinese label (e.g. '天乙贵人', '海中金', '比肩')
 *   3. ten-god alias       (e.g. '元男' → Day Master, '偏官' → Seven Killings)
 *   4. Na Yin by GanZhi    (e.g. '甲子' → Sea Gold)
 *   5. interaction by verb (e.g. '午子相冲' → Clash)
 * Falls back to the original input when nothing matches.
 *
 * @example translate('元男')          // 'Day Master'
 * @example translate('午子相冲')       // 'Clash'
 * @example translate('甲子', 'zh')    // '海中金'
 */
export function translate(input: string, lang: Lang = 'en'): string {
  const term =
    TERM_BY_KEY[input] ??
    TERM_BY_ZH[input] ??
    tenGodByZh(input) ??
    naYinOf(input) ??
    interactionFromZh(input);
  if (!term) return input;
  return lang === 'zh' ? term.zh : term.en;
}
